BEGIN;
SET LOCAL ROLE service_role;
DO $verification$ DECLARE result jsonb; caught boolean:=false; BEGIN
 IF (NOT EXISTS(SELECT 1 FROM public.clinics WHERE id='postgres-verification')) IS NOT TRUE THEN RAISE EXCEPTION 'Verification fixture already exists'; END IF;
 PERFORM public.linguar_batch('[{"id":"4643d1cf73d86abde8ee9029","args":["postgres-verification","verification","Verification only","2026-10-07T16:00:00Z"]},{"id":"0a88fe9ef577dbbadfcc4fb6","args":["postgres-verification:patient","postgres-verification","patient","{\"name\":\"Fictitious test\",\"age\":6,\"therapist\":\"owner-profile\",\"shareAuthorized\":\"Sim\",\"guardianEmail\":\"parent@example.invalid\",\"status\":\"Ativo\"}","verification","2026-10-07T16:00:00Z"]},{"id":"0a88fe9ef577dbbadfcc4fb6","args":["postgres-verification:appointment","postgres-verification","appointment","{\"patientId\":\"patient\",\"therapist\":\"owner-profile\",\"date\":\"2026-10-07\",\"time\":\"09:00\",\"duration\":45,\"status\":\"Esperado\"}","verification","2026-10-07T16:00:00Z"]},{"id":"0a88fe9ef577dbbadfcc4fb6","args":["postgres-verification:guard-appointment","postgres-verification","appointment","{\"patientId\":\"patient\",\"therapist\":\"owner-profile\",\"date\":\"2026-10-07\",\"time\":\"10:00\",\"duration\":45,\"status\":\"Esperado\"}","verification","2026-10-07T16:00:00Z"]},{"id":"0a88fe9ef577dbbadfcc4fb6","args":["postgres-verification:plan","postgres-verification","plan","{\"patientId\":\"patient\",\"status\":\"Ativo\",\"goals\":[{\"id\":\"goal\",\"name\":\"Test goal\"}]}","verification","2026-10-07T16:00:00Z"]},{"id":"0a88fe9ef577dbbadfcc4fb6","args":["postgres-verification:proposal","postgres-verification","plan","{\"patientId\":\"patient\",\"status\":\"Por aprovar\",\"basePlanId\":\"plan\",\"basePlanVersion\":1}","verification","2026-10-07T16:00:00Z"]},{"id":"2c24be4ec3141cee2b244147","args":["postgres-verification:grant","postgres-verification","patient","parent@example.invalid",1,"2026-10-07T16:00:00Z","postgres-verification:patient","postgres-verification",1]}]'::jsonb);
 result:=public.linguar_batch('[{"id":"1c801c90a37acabb6ddb7e71","args":["postgres-verification:session","postgres-verification","session","{\"patientId\":\"patient\",\"appointmentId\":\"appointment\",\"summary\":\"Test clinical record\",\"internalNote\":\"Internal\",\"mutationId\":\"session-operation\"}","verification","2026-10-07T16:00:00Z","postgres-verification:appointment","postgres-verification",1,"postgres-verification:patient","postgres-verification",1,"postgres-verification:plan","postgres-verification",1]},{"id":"e569047c43891b6a7d7403a1","args":["2026-10-07T16:00:00Z","postgres-verification:appointment","postgres-verification","postgres-verification:session","session-operation"]},{"id":"785d2aa702d24e1a7c45ce92","args":["postgres-verification:session-notice","postgres-verification","careNotice","{\"patientId\":\"patient\",\"type\":\"session\"}","verification","2026-10-07T16:00:00Z","postgres-verification:session","session-operation"]},{"id":"fd0c2614bdb31ec7c194dfb9","args":["postgres-verification-session-operation","postgres-verification","verification","care-update","postgres-verification:session","2026-10-07T16:00:00Z","postgres-verification:session","session-operation"]}]'::jsonb);
 IF (result->0->'meta'->>'changes'='1') IS NOT TRUE THEN RAISE EXCEPTION 'Session was not saved'; END IF;
 IF ((SELECT data::jsonb->>'status' FROM public.records WHERE id='postgres-verification:appointment')='Concluída') IS NOT TRUE THEN RAISE EXCEPTION 'Appointment did not finish'; END IF;
 IF (EXISTS(SELECT 1 FROM public.audit WHERE id='postgres-verification-session-operation')) IS NOT TRUE THEN RAISE EXCEPTION 'Session audit is missing'; END IF;
 result:=public.linguar_batch('[{"id":"1c801c90a37acabb6ddb7e71","args":["postgres-verification:guard-session","postgres-verification","session","{\"patientId\":\"patient\",\"appointmentId\":\"guard-appointment\",\"summary\":\"Test clinical record\",\"internalNote\":\"Internal\",\"mutationId\":\"patient-stale-operation\"}","verification","2026-10-07T16:00:00Z","postgres-verification:guard-appointment","postgres-verification",1,"postgres-verification:patient","postgres-verification",0,"postgres-verification:plan","postgres-verification",1]},{"id":"e569047c43891b6a7d7403a1","args":["2026-10-07T16:00:00Z","postgres-verification:guard-appointment","postgres-verification","postgres-verification:guard-session","patient-stale-operation"]},{"id":"785d2aa702d24e1a7c45ce92","args":["postgres-verification:guard-session-notice","postgres-verification","careNotice","{\"patientId\":\"patient\",\"type\":\"session\"}","verification","2026-10-07T16:00:00Z","postgres-verification:guard-session","patient-stale-operation"]},{"id":"fd0c2614bdb31ec7c194dfb9","args":["postgres-verification-patient-stale-operation","postgres-verification","verification","care-update","postgres-verification:guard-session","2026-10-07T16:00:00Z","postgres-verification:guard-session","patient-stale-operation"]}]'::jsonb);
 IF (result->0->'meta'->>'changes'='0') IS NOT TRUE THEN RAISE EXCEPTION 'Patient version change was ignored'; END IF;
 IF (NOT EXISTS(SELECT 1 FROM public.records WHERE id IN ('postgres-verification:guard-session','postgres-verification:guard-session-notice')) AND NOT EXISTS(SELECT 1 FROM public.audit WHERE id='postgres-verification-patient-stale-operation')) IS NOT TRUE THEN RAISE EXCEPTION 'Patient version conflict left clinical effects'; END IF;
 IF ((SELECT data::jsonb->>'status' FROM public.records WHERE id='postgres-verification:guard-appointment')='Esperado') IS NOT TRUE THEN RAISE EXCEPTION 'Patient version conflict concluded the appointment'; END IF;
 result:=public.linguar_batch('[{"id":"4a835095a85590b8cf1b63b2","args":["{\"mutationId\":\"stale\"}","2026-10-07T16:00:00Z","postgres-verification:session","postgres-verification",0]},{"id":"785d2aa702d24e1a7c45ce92","args":["postgres-verification:stale-notice","postgres-verification","careNotice","{\"body\":\"Must not exist\"}","verification","2026-10-07T16:00:00Z","postgres-verification:session","stale"]}]'::jsonb);
 IF (result->0->'meta'->>'changes'='0') IS NOT TRUE THEN RAISE EXCEPTION 'Stale write was accepted'; END IF;
 IF (NOT EXISTS(SELECT 1 FROM public.records WHERE id='postgres-verification:stale-notice')) IS NOT TRUE THEN RAISE EXCEPTION 'Stale write left a notification'; END IF;
 PERFORM public.linguar_batch('[{"id":"631b12c13578082c75720361","args":["{\"patientId\":\"patient\",\"status\":\"Ativo\",\"mutationId\":\"revision\"}","2026-10-07T16:00:00Z","postgres-verification:proposal","postgres-verification",1,"postgres-verification:plan","postgres-verification",1]},{"id":"785d2aa702d24e1a7c45ce92","args":["postgres-verification:snapshot","postgres-verification","planSnapshot","{\"originalPlanId\":\"plan\",\"status\":\"Ativo\"}","verification","2026-10-07T16:00:00Z","postgres-verification:proposal","revision"]},{"id":"e3875410151464e370d3d729","args":["proposal","2026-10-07T16:00:00Z","postgres-verification:plan","postgres-verification:proposal","revision"]},{"id":"fd0c2614bdb31ec7c194dfb9","args":["postgres-verification-revision","postgres-verification","verification","care-update","postgres-verification:proposal","2026-10-07T16:00:00Z","postgres-verification:proposal","revision"]}]'::jsonb);
 IF (EXISTS(SELECT 1 FROM public.records WHERE id='postgres-verification:snapshot') AND (SELECT data::jsonb->>'status' FROM public.records WHERE id='postgres-verification:plan')='Substituído') IS NOT TRUE THEN RAISE EXCEPTION 'Plan revision was partial'; END IF;
 IF (EXISTS(SELECT 1 FROM public.audit WHERE id='postgres-verification-revision')) IS NOT TRUE THEN RAISE EXCEPTION 'Plan approval audit is missing'; END IF;
 PERFORM public.linguar_batch('[{"id":"4a835095a85590b8cf1b63b2","args":["{\"patientId\":\"patient\",\"status\":\"Concluído\",\"closedReason\":\"Synthetic verification\",\"closedBy\":\"verification\",\"mutationId\":\"close-plan\"}","2026-10-07T16:00:00Z","postgres-verification:proposal","postgres-verification",2]},{"id":"785d2aa702d24e1a7c45ce92","args":["postgres-verification:closed-snapshot","postgres-verification","planSnapshot","{\"originalPlanId\":\"proposal\",\"originalPlanVersion\":2,\"status\":\"Ativo\"}","verification","2026-10-07T16:00:00Z","postgres-verification:proposal","close-plan"]},{"id":"785d2aa702d24e1a7c45ce92","args":["postgres-verification:closed-notice","postgres-verification","careNotice","{\"patientId\":\"patient\",\"type\":\"plan\"}","verification","2026-10-07T16:00:00Z","postgres-verification:proposal","close-plan"]},{"id":"fd0c2614bdb31ec7c194dfb9","args":["postgres-verification-close-plan","postgres-verification","verification","care-update","postgres-verification:proposal","2026-10-07T16:00:00Z","postgres-verification:proposal","close-plan"]}]'::jsonb);
 IF ((SELECT data::jsonb->>'status' FROM public.records WHERE id='postgres-verification:proposal')='Concluído' AND (SELECT data::jsonb->>'status' FROM public.records WHERE id='postgres-verification:closed-snapshot')='Ativo') IS NOT TRUE THEN RAISE EXCEPTION 'Plan closure did not preserve its approved version'; END IF;
 IF (EXISTS(SELECT 1 FROM public.audit WHERE id='postgres-verification-close-plan') AND EXISTS(SELECT 1 FROM public.records WHERE id='postgres-verification:closed-notice')) IS NOT TRUE THEN RAISE EXCEPTION 'Plan closure audit or notice is missing'; END IF;
 PERFORM public.linguar_batch('[{"id":"4a835095a85590b8cf1b63b2","args":["{\"name\":\"Fictitious test\",\"shareAuthorized\":\"Não\",\"guardianEmail\":\"parent@example.invalid\",\"mutationId\":\"revoke\"}","2026-10-07T16:00:00Z","postgres-verification:patient","postgres-verification",1]},{"id":"98d53363f5f2f76a5a9949e4","args":["postgres-verification","patient","postgres-verification:patient","revoke"]}]'::jsonb);
 IF ((SELECT enabled FROM public.family_access WHERE id='postgres-verification:grant')=0) IS NOT TRUE THEN RAISE EXCEPTION 'Consent did not revoke access'; END IF;
 BEGIN PERFORM public.linguar_batch('[{"id":"0a88fe9ef577dbbadfcc4fb6","args":["postgres-verification:rollback","postgres-verification","patient","{\"name\":\"Must not persist\"}","verification","2026-10-07T16:00:00Z"]},{"id":"unknown-query","args":[]}]'::jsonb); EXCEPTION WHEN OTHERS THEN caught:=true; END;
 IF (caught) IS NOT TRUE THEN RAISE EXCEPTION 'Invalid query did not fail'; END IF;
 IF (NOT EXISTS(SELECT 1 FROM public.records WHERE id='postgres-verification:rollback')) IS NOT TRUE THEN RAISE EXCEPTION 'Failed transaction left a patient'; END IF;
END $verification$;
ROLLBACK;
SELECT 'sessions, patient version guards, stale writes, plan revisions and closure, audit, consent revocation and transaction rollback passed' AS verification,
 (SELECT count(*) FROM public.records) AS persistent_patient_data;
